import sys

def myPow(x: float, n: int) -> float:
    if n == 0: return 1.0
    if n < 0:
        x = 1 / x
        n = -n
    res = 1.0
    while n > 0:
        if n % 2 == 1:
            res *= x
        x *= x
        n //= 2
    return res

if __name__ == '__main__':
    lines = sys.stdin.read().strip().split('\n')
    if len(lines) < 2: sys.exit(0)
    x = float(lines[0].strip())
    n = int(lines[1].strip())
    print(f"{myPow(x, n):.5f}")

