#include <iostream>
#include <iomanip>

using namespace std;

double myPow(double x, int n) {
    long long N = n;
    if (N < 0) {
        x = 1 / x;
        N = -N;
    }
    double res = 1.0;
    while (N > 0) {
        if (N % 2 == 1) res *= x;
        x *= x;
        N /= 2;
    }
    return res;
}

int main() {
    double x; int n;
    if (!(cin >> x >> n)) return 0;
    cout << fixed << setprecision(5) << myPow(x, n) << endl;
    return 0;
}

