            x = 1 / x;
            N = -N;
        }
        double res = 1.0;
        while (N > 0) {
            if (N % 2 == 1) res *= x;
            x *= x;
            N /= 2;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextDouble()) return;
        double x = sc.nextDouble();
        int n = sc.nextInt();
        System.out.printf("%.5f\n", myPow(x, n));
    }
}

