const fs = require('fs');

function myPow(x, n) {
    if (n === 0) return 1.0;
    if (n < 0) {
        x = 1 / x;
        n = -n;
    }
    let res = 1.0;
    while (n > 0) {
        if (n % 2 === 1) res *= x;
        x *= x;
        n = Math.floor(n / 2);
    }
    return res;
}

